wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_read;

struct Node;

impl Guest for Node {
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        // DropSeen: keep only items whose id is absent from the 'seen' store.
        // The store is read-only (state-read exposes `get` and nothing else),
        // so this run observes what prior runs recorded without mutating it.
        // `id` is the parser's digest, not feed-chosen text, so it is a safe
        // lookup key; the adversarial free-text fields are never used here.
        items
            .into_iter()
            .filter(|item| state_read::get(&item.id).is_none())
            .collect()
    }
}

export!(Node);
